"""Freeze one immutable QA iteration in this exclusive run; no canonical/shared writes."""
from pathlib import Path
import argparse,json,hashlib,shutil,datetime,difflib
B=Path(__file__).parent.resolve();ROOT=Path('/home/jonny/projects/boardgame-rules')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
p=argparse.ArgumentParser();p.add_argument('benchmark');p.add_argument('iteration');p.add_argument('--expected-summary-sha',required=True);p.add_argument('--previous');a=p.parse_args()
K=(B/a.benchmark).resolve();I=(B/a.iteration).resolve();assert K.is_relative_to(B) and I.is_relative_to(B)
assert not I.exists(),'Never overwrite an existing iteration';freeze=json.loads((K/'freeze.json').read_text());assert all(sha(K/n)==h for n,h in freeze['hashes'].items())
S=ROOT/'rules/new-angeles.md';assert sha(S)==a.expected_summary_sha,'Canonical changed unexpectedly: coordinate before freezing'
q=json.loads((K/'questions.json').read_text());key=json.loads((K/'answer-key.json').read_text());scope=json.loads((K/'asked-clause-map.json').read_text());ids=[x['id'] for x in q['questions']];assert len(ids)==len(set(ids))==len(key['answers'])==len(scope);assert set(ids)=={x['id'] for x in key['answers']}=={x['id'] for x in scope}
helper=q['generic_reader_process'];assert hashlib.sha256(helper['source_extractor_python'].encode()).hexdigest()==helper['source_extractor_sha256'];assert helper['source_extractor_sha256']==sha(ROOT/'docs/quality/summary-qa/batches/2026-11-05-batch-002957/generic-reader-method/v10/source_units.py')
original=json.loads((B/'input-manifest.json').read_text())['sources'];assert all(sha(s)==v['sha256'] for s,v in original.items())
I.mkdir();shutil.copyfile(S,I/'summary-snapshot.md');shutil.copyfile(K/'questions.json',I/'questions.json')
protocol="You are a NEW independent blind rules-summary reader. The only game-data inputs are these two frozen files:\n{summary}\n{questions}\n\nThe guide is the sole rules authority. The questions JSON embeds rule-agnostic extraction code; execute that code in memory and choose your own source offsets. Do not read an external helper, source books, keys, required-fact maps, old runs, grades, repair history, other readers' work, or parent artifacts. No browsing or coordination/status tools. Derive every clause, query, source selection and result yourself from the literal question and guide. No supplied question-to-source routing exists.\n\nFirst read BOTH complete inputs in contiguous exact Unicode ranges of AT MOST5500 characters, ONE range per tool result, outer output cap >=6000tokens. Compute each end=min(start+5500,total); never merge a final remainder into an oversized range. Print path/start/end/total and exact text. Verify no truncation and retain actual range/hash receipts. Line counts are insufficient. Execute the embedded extractor only after its full code is available; it supplies structure, never game facts.\n\nWork in sequential batches of AT MOST8 questions. Keep your current draft in persistent tool memory or your own current work product; it is not a rules authority. Only the guide and literal questions may supply game data. Use no other files or previous-run outputs. You may write current progress only to your assigned output below. Do not fill unfinished IDs with placeholder or unsupported answers.\n\nFor EACH question:\n\n1. Split every actual ask, contrast and supplied case into atomic clauses. Separate distinct timing, actor, condition, location, quantity and outcome requests when they are asked. Copy each clause's literal question span and offsets. Do not use the entire multi-part question as one undifferentiated clause. Do not turn true unasked background into extra required clauses.\n2. For EACH clause, choose your own search terms from the literal question and guide and search the ENTIRE guide. Inspect relevant matches instead of taking an arbitrary first hit or assigning a whole question to one section by one keyword. Each named item needs its own governing text; a reference to a different item is insufficient. A general rule and a named exception may require separate source units.\n3. Select complete governing units with embedded extract_unit(guide,offset). Read the selected operative text in model-visible tool output before deriving the clause's result. Render long units in contiguous <=5500-character ranges; never crop away controlling text. Preserve procedure peer/child steps, full actual table rows/headers/all cells, relevant introductory definitions and legends. Do not dump unrelated sections. Check controlling qualifications and exceptions in the guide.\n4. Validate every extraction record with validate_record. This validates structure/ranges; it does NOT prove that the unit governs this clause or contains all requested facts. Check relevance and completeness yourself against the literal ask.\n5. Store one checked result per clause. For an ordinary lookup, use the relevant exact operative source text where it supplies the answer, rather than adding an unnecessary second paraphrase. For an actual supplied case, explicitly decide its result: evaluate comparisons, arithmetic, actor choices and final states using the guide. A threshold or general conditional alone does not answer a requested concrete outcome. Use code to check arithmetic/comparisons when helpful. Keep correct conditional outcomes when relevant conditions were not supplied; never invent changed givens.\n6. Each clause record must include asked_text, asked_start, asked_end, queries, mode(lookup or case), result, and evidence_indices into that question's evidence array. Assert question[asked_start:asked_end]==asked_text. For cases include the actual given data and evaluated work/outcome; for lookups identify the exact governing statement. The source selections and clause descriptions are your own work, not a hidden key.\n7. Render the overall answer mechanically from those same checked clause results. Do not hand-write a second inconsistent narrative. Recheck every substantive field, not only the final answer. A correct quote does not excuse a wrong actor, amount, destination, timing or case result elsewhere.\n\nAfter EACH batch, verify every requested part is represented, each result is supported by its chosen governing text, all actual cases have actual decisions, all extraction records validate, and all repeated fields agree. If a clause is genuinely absent after whole-guide search, state that absence explicitly and do not guess. Lack of time or unfinished work is not evidence that a rule is absent. Confidence/support labels and source-format bookkeeping are separate from factual correctness.\n\nWrite valid JSON ONLY to {output}, containing reader, inputs_read, answers and optional batch-progress metadata. Each answer has id, clauses(the structured records above), answer, support(supported/partial/unsupported), and evidence(array of complete validated extraction records). Include every actual questions-array ID exactly once when finished; N is its actual length. All fields remain subject to factual grading. Do not evaluate or repair the guide.\n\nContinue the same source-only task until all N substantive answers are complete. If a real per-turn limit requires a pause, save truthful current progress and report its completed count so your own unfinished task can continue without any factual feedback. Do not claim completion or manufacture placeholder entries. Final reply only the saved path/count once all N are complete.\n"
for l in ['a','b']:(I/f'reader-{l}-prompt.txt').write_text(protocol.format(summary=I/'summary-snapshot.md',questions=I/'questions.json',output=I/f'reader-{l}.json'))
assert (I/'reader-a-prompt.txt').read_text().replace('reader-a.json','reader-b.json')==(I/'reader-b-prompt.txt').read_text()
meta={'benchmark':a.benchmark,'question_count':len(ids),'expected_ids':ids,'scope_status':freeze['scope_status'],'scope_limit':freeze.get('scope_limit'),'requested_model':'gpt-6-luna','requested_effort':'high','fork_turns':'none','protocol':'atomic-clause-source-checks-v6-embedded-extractor-v10','protocol_template_sha256':sha(B/'reader-protocol-v6.txt'),'generic_extractor_unchanged':True,'maximum_answer_batch_questions':8,'frozen_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'hashes':{n:sha(I/n) for n in ['summary-snapshot.md','questions.json','reader-a-prompt.txt','reader-b-prompt.txt']},'key_sha256':sha(K/'answer-key.json'),'asked_clause_map_sha256':sha(K/'asked-clause-map.json'),'benchmark_freeze_sha256':sha(K/'freeze.json'),'authoritative_sources_unchanged':True,'helper_sha256':helper['source_extractor_sha256'],'identical_instructions_except_output_path':True}
(I/'input-manifest.json').write_text(json.dumps(meta,indent=2)+'\n')
if a.previous:
 P=(B/a.previous/'summary-snapshot.md').resolve();assert P.is_relative_to(B);(I/'summary-changes.patch').write_text(''.join(difflib.unified_diff(P.read_text().splitlines(True),S.read_text().splitlines(True),fromfile=str(P.relative_to(B)),tofile=a.iteration+'/summary-snapshot.md')))
print(json.dumps({'iteration':str(I),'question_count':len(ids),'summary_sha256':sha(I/'summary-snapshot.md'),'status':'frozen, not dispatched'}))
